seen = {'archive search speed', 'archive search speed index'}
def lev(a, b): return sum(1 for x, y in zip(a, b) if x != y) + abs(len(a) - len(b))
new_q = 'archive search speed index'
blocked = any(lev(new_q, s) / max(1, len(new_q)) < 0.1 for s in seen)
print('query blocked as repeat:', blocked)

